\end{scope}
\draw (4.2,3.3) rectangle (7.6,5.8);
\draw (5.43,4.4) circle (0.8);
\draw (6.37,4.4) circle (0.8);
\node at (4.92,5.45) {$N$};
\node at (6.88,5.45) {$S$};
\node at (5.9,2.95) {$B$};
\fill[gray!35] (0,0) rectangle (3.4,2.5);
\fill[white] (1.23,1.1) circle (0.8);
\fill[white] (2.17,1.1) circle (0.8);
\draw (0,0) rectangle (3.4,2.5);
\draw (1.23,1.1) circle (0.8);
\draw (2.17,1.1) circle (0.8);
\node at (0.72,2.15) {$N$};
\node at (2.68,2.15) {$S$};
